def length_of_longest_substring(s):
    last = {}                          # char → last index seen
    l = best = 0
    for r, c in enumerate(s):
        if c in last:
            l = max(l, last[c] + 1)    # never move l backwards
        last[c] = r
        best = max(best, r - l + 1)
    return best

