from bisect import bisect_right

def min_sub_array_len(target, nums):
    n = len(nums)
    pre = [0] * (n + 1)                # pre is increasing: all values positive
    for i, x in enumerate(nums):
        pre[i + 1] = pre[i] + x
    best = float('inf')
    for r in range(1, n + 1):
        # rightmost l with pre[l] <= pre[r] - target, i.e. sum(l..r) >= target
        l = bisect_right(pre, pre[r] - target) - 1
        if l >= 0:
            best = min(best, r - l)
    return 0 if best == float('inf') else best

