from collections import Counter

def min_window(s, t):
    need = Counter(t)
    best = ""
    for i in range(len(s)):
        for j in range(i + len(t), len(s) + 1):
            window = Counter(s[i:j])   # re-count the whole substring
            if all(window[c] >= need[c] for c in need):
                if not best or j - i < len(best):
                    best = s[i:j]
                break                  # longer windows from i can only be worse
    return best
